APXF["ar-el-paraiso"] = {"lede": "El Paraíso is a small IG in Maipú's Fray Luis Beltrán area, along the Mendoza river, recognised in 2007 for its traditional red-wine vineyards.", "facts": [["Category", "IG"], ["Recognized", "2007 (INV Res. C.28/2007)"]], "sections": [["The place", ""], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["In the glass", "<p>Malbec, Cabernet, Bonarda and blends, ripened under strong sun and cooled by mountain nights.</p>"], ["For the exam", "<p>IG in Mendoza province; recognised 2007 (INV Res. C.28/2007).</p>"]], "producers": [], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-el-peral"] = {"lede": "El Peral is a district of Tupungato at about 1,100 to 1,300 m, recognised as an IG at the request of Bodegas Chandon.", "facts": [["Category", "IG"], ["Recognized", "2022 (RESOL-2022-1-APN-INV#MEC)"]], "sections": [["The place", "<p>Chandon grows sparkling-base Chardonnay and Pinot Noir here; cool nights and stony soils also give fresh Malbec.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["In the glass", "<p>Malbec, Cabernet, Bonarda and blends, ripened under strong sun and cooled by mountain nights.</p>"], ["For the exam", "<p>IG in Mendoza province; recognised 2022 (RESOL-2022-1-APN-INV#MEC).</p>"]], "producers": ["Bodegas Chandon"], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-general-alvear"] = {"lede": "General Alvear, east of San Rafael on the Atuel river, is Mendoza's southernmost wine department, with about 3,100 ha (INV 2024) of mostly traditional varieties and everyday wine.", "facts": [["Category", "IG"], ["Recognized", "2002 (INV Res. C.32/2002)"], ["Vineyard area", "About 3,095 ha"]], "sections": [["The place", ""], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["In the glass", "<p>Malbec, Cabernet, Bonarda and blends, ripened under strong sun and cooled by mountain nights.</p>"], ["For the exam", "<p>IG in Mendoza province; part of the first big list of department-level IGs registered by the INV in 2002 (Res. C.32/2002).</p>"]], "producers": [], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-godoy-cruz"] = {"lede": "Godoy Cruz, now part of Greater Mendoza, was a 19th-century wine town.", "facts": [["Category", "IG"], ["Recognized", "2002 (INV Res. C.32/2002)"]], "sections": [["The place", "<p>It keeps historic wineries such as Escorihuela Gascón (founded 1884) and Bodega Arizu, though the IG's vineyards have almost all given way to the city.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["In the glass", "<p>Malbec, Cabernet, Bonarda and blends, ripened under strong sun and cooled by mountain nights.</p>"], ["For the exam", "<p>IG in Mendoza province; part of the first big list of department-level IGs registered by the INV in 2002 (Res. C.32/2002).</p>"]], "producers": ["Escorihuela Gascón"], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-gualtallary"] = {"lede": "Gualtallary, a district of Tupungato rising from about 1,200 to 1,600 m, is the closest thing Argentina has to a grand cru.", "facts": [["Category", "IG"], ["Recognized", "Provisional ('mención precaria'), INV; definitive status unconfirmed"], ["Main grapes", "Malbec, Chardonnay, Cabernet Franc, Pinot Noir"]], "sections": [["The place", "<p>Nicolás Catena's Adrianna vineyard, planted in 1992 at about 1,450 m when everyone said the site was too cold, gave the world-famous Adrianna Malbecs and White Bones and White Stones Chardonnays. Soils are shallow alluvial gravels and sand over limestone (calcium carbonate) crusts, sometimes with fossil-bearing caliche; the light is intense and the nights cold.</p><p>Gualtallary wines are electric: violet-scented, chalk-textured Malbec, taut Chardonnay, and Cabernet Franc with herbal lift. Zuccardi, El Enemigo, SuperUco and Huentala all farm here. Its IG application ran into disputes over the boundary; INV's 2023 statistics list it as a 'mención precaria' (a provisional authorisation to label) and I found no confirmation of definitive registration as of October 2026.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["History", "<p>Catena's Adrianna vineyard, planted in 1992 at about 1,450 m, produced Malbec and Chardonnay that changed opinion about how high Argentine vineyards could go; its White Bones and White Stones Chardonnays and River Stones and Mundus Bacillus Terrae Malbecs are single-plot wines from calcareous soils. Gualtallary has applied for IG status and is recognised only provisionally.</p>"], ["In the glass", "<p>Taut, floral, mineral Malbec; chalky Chardonnay.</p>"], ["For the exam", "<p>Tupungato; Adrianna vineyard 1992; calcareous soils; provisional IG.</p>"]], "producers": ["Catena Zapata (Adrianna)", "Zuccardi", "El Enemigo", "SuperUco", "Huentala"], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-guaymallen"] = {"lede": "Guaymallén, on the eastern side of Mendoza city, is a historic wine department now largely urban; under 500 ha of vines remain (INV 2024), mostly Malbec and Criolla.", "facts": [["Category", "IG"], ["Recognized", "2002 (INV Res. C.32/2002)"]], "sections": [["The place", ""], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["In the glass", "<p>Malbec, Cabernet, Bonarda and blends, ripened under strong sun and cooled by mountain nights.</p>"], ["For the exam", "<p>IG in Mendoza province; part of the first big list of department-level IGs registered by the INV in 2002 (Res. C.32/2002).</p>"]], "producers": [], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-junin"] = {"lede": "Junín, in Eastern Mendoza, has about 10,800 ha of vines (INV 2024) and a reputation for generous Bonarda and Malbec from warm, sandy soils.", "facts": [["Category", "IG"], ["Recognized", "2002 (INV Res. C.32/2002)"], ["Vineyard area", "About 10,849 ha"]], "sections": [["The place", ""], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["In the glass", "<p>Malbec, Cabernet, Bonarda and blends, ripened under strong sun and cooled by mountain nights.</p>"], ["For the exam", "<p>IG in Mendoza province; part of the first big list of department-level IGs registered by the INV in 2002 (Res. C.32/2002).</p>"]], "producers": [], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-la-consulta"] = {"lede": "La Consulta, a district of San Carlos at about 950 to 1,100 m, is old Malbec country: dozens of growers farm vineyards planted in the mid-20th century on deep alluvial soils.", "facts": [["Category", "IG"], ["Recognized", "2014 (INV Res. C.19/2014)"]], "sections": [["The place", "<p>It was recognised in 2014 at the request of Leoncio Arizu, and many of the region's best old-vine Malbecs are sourced here.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["History", "<p>La Consulta holds some of Uco's oldest Malbec vineyards, planted decades before the 1990s boom.</p>"], ["In the glass", "<p>Old-vine Malbec with depth and spice.</p>"], ["For the exam", "<p>San Carlos; old Malbec; IG 2014.</p>"]], "producers": ["Leoncio Arizu (Luigi Bosca)", "O. Fournier", "Finca La Celia"], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-la-paz"] = {"lede": "La Paz is Mendoza's easternmost wine department, hot and dry on the border with San Luis, with only about 135 ha of vines (INV 2024).", "facts": [["Category", "IG"], ["Recognized", "2002 (INV Res. C.32/2002)"]], "sections": [["The place", ""], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["In the glass", "<p>Malbec, Cabernet, Bonarda and blends, ripened under strong sun and cooled by mountain nights.</p>"], ["For the exam", "<p>IG in Mendoza province; part of the first big list of department-level IGs registered by the INV in 2002 (Res. C.32/2002).</p>"]], "producers": [], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-las-compuertas"] = {"lede": "Las Compuertas, at about 1,050 m on the north side of Luján de Cuyo by the Mendoza river, holds some of Argentina's oldest Malbec vineyards, many planted in the early 20th century and still own-rooted.", "facts": [["Category", "IG"], ["Recognized", "2007 (INV Res. C.30/2007)"]], "sections": [["The place", "<p>Poor, stony alluvial soils and the cooling effect of the river's canyon give fragrant, fine-grained Malbec. Cheval des Andes and many old-vine cuvées source here.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["History", "<p>Las Compuertas, named after the irrigation gates on the Mendoza river, has some of Argentina's oldest ungrafted Malbec, planted in the early twentieth century, prized for single-vineyard Malbec.</p>"], ["In the glass", "<p>Elegant old-vine Malbec.</p>"], ["For the exam", "<p>Luján de Cuyo; old ungrafted Malbec; highest part of the district, about 1,050 m.</p>"]], "producers": ["Cheval des Andes", "Terrazas de los Andes", "Durigutti"], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-las-heras"] = {"lede": "Las Heras stretches from Mendoza city north-west into the high Andes along the road to Chile.", "facts": [["Category", "IG"], ["Recognized", "2002 (INV Res. C.32/2002)"]], "sections": [["The place", "<p>Its vineyards (about 1,300 ha in 2024) lie near the city; the separate Canota IG covers a higher piedmont site.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["In the glass", "<p>Malbec, Cabernet, Bonarda and blends, ripened under strong sun and cooled by mountain nights.</p>"], ["For the exam", "<p>IG in Mendoza province; part of the first big list of department-level IGs registered by the INV in 2002 (Res. C.32/2002).</p>"]], "producers": [], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-lavalle"] = {"lede": "Lavalle, north of Mendoza city, is the province's driest and lowest wine department (around 600 m), with about 12,300 ha of vines (INV 2024) for bulk wine, juice and grape concentrate.", "facts": [["Category", "IG"], ["Recognized", "2002 (INV Res. C.32/2002; synonym Desierto de Lavalle 2009)"], ["Vineyard area", "About 12,290 ha"]], "sections": [["The place", "<p>The synonym 'Desierto de Lavalle' was added in 2009 for wines from its sandy, desert vineyards.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["In the glass", "<p>Malbec, Cabernet, Bonarda and blends, ripened under strong sun and cooled by mountain nights.</p>"], ["For the exam", "<p>IG in Mendoza province; part of the first big list of department-level IGs registered by the INV in 2002 (Res. C.32/2002).</p>"]], "producers": [], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-los-chacayes"] = {"lede": "Los Chacayes is an alluvial fan at 1,100 to 1,600 m in western Tunuyán, recognised as an IG in 2017.", "facts": [["Category", "IG"], ["Recognized", "2017 (RESOL-2017-249-APN-INV#MA)"]], "sections": [["The place", "<p>Its soils are among the stoniest in Uco, with big river boulders and little fine material, and the vines struggle: Malbec here is dark, tannic and mountain-fresh. François Lurton's Bodega Piedra Negra and Corazón del Sol are among the estates here.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["History", "<p>A wide alluvial fan in Tunuyán, colonised from the late 1990s by projects such as Bodega Piedra Negra and later many single-vineyard Malbecs; recognised as an IG in 2017.</p>"], ["In the glass", "<p>Concentrated, structured Malbec and Cabernet Franc.</p>"], ["For the exam", "<p>Tunuyán; IG 2017; alluvial fan 1,100 to 1,600 m.</p>"]], "producers": ["Bodega Piedra Negra (Lurton)", "Corazón del Sol"], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-lujan-de-cuyo"] = {"lede": "Luján de Cuyo is Argentina's first denomination of origin and the historic home of fine Malbec.", "facts": [["Category", "DOC"], ["Recognized", "DOC 1989/1993 (sources differ); registered by INV Res. C.15/2005"], ["Vineyard area", "About 15,210 ha"], ["Main grapes", "Malbec (8,920 ha of the department's 15,210 ha in 2024), Cabernet Sauvignon, Chardonnay, Petit Verdot"]], "sections": [["The place", "<p>The department lies just south of Mendoza city on the first terrace of the Mendoza river at 850 to 1,100 m, and from the late 19th century its districts (Vistalba, Las Compuertas, Chacras de Coria, Mayor Drummond, Perdriel, Agrelo, Ugarteche) were planted by Italian, Spanish and French families. Many vineyards are 60 to over 100 years old and own-rooted.</p><p>The DOC was pushed through by local producers in the late 1980s and early 1990s to defend Malbec's reputation; INV registered it under the 1999 national law in 2005. It is the only Argentine DOC in regular use: INV reported 382,866 litres exported and 511,537 litres sold domestically under the DOC in 2022. Its terroir divides north to south. The northern districts near the river (Vistalba, Las Compuertas, Chacras, Drummond) have stony alluvial soils and give perfumed, elegant Malbec. The southern districts of Perdriel, Agrelo and Ugarteche have deeper clay-loam and give broader, darker wines. Agrelo, Las Compuertas, Vistalba and Alto Agrelo also have their own IGs.</p><p>Luján Malbec is the classic Argentine style: plum, violet and mocha, ripe and velvety, built for ageing in the best old-vine cuvées.</p><p>Alluvial terraces of the Mendoza river, stony near the river in the north, deeper clay-loam over gravel to the south; 850 to 1,100 m; about 200 mm of rain, wide day-night swings.</p>"], ["The rules", "<p>A controlled designation of origin. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it. The Luján de Cuyo DOC regulation requires wines from registered vineyards in the department at least 10 years old, planted at no less than 5,000 vines per hectare and yielding no more than 10 tonnes per hectare; reds must be at least 85% Malbec, aged at least one year in barrel and two years in all before release, and the wine must be made and bottled in Luján de Cuyo.</p>"], ["History", "<p>Luján de Cuyo, on the high bank of the Mendoza river south of the city, was where the first generation of fine-wine wineries grew in the twentieth century, with old ungrafted Malbec vineyards in Perdriel, Vistalba, Las Compuertas and Agrelo. Producers formed a promotion council and created Argentina's first DOC around 1989, recognised by the INV in the early 1990s (sources differ on the date) and registered in 2005. For years only a handful of wineries used it. In the 2020s new members joined the six founders, and the council began to define district profiles within the department.</p>"], ["In the glass", "<p>Malbec of violet, plum and sweet spice, with ripe, fine tannins and good ageing potential.</p>"], ["For the exam", "<p>Argentina's first DOC (c. 1989); 85% Malbec; vines 10+ years; 10 t/ha; 1 year in barrel, 2 years before release.</p>"]], "producers": ["Catena Zapata", "Achával-Ferrer", "Cheval des Andes", "Terrazas de los Andes", "Norton", "Bodega Weinert", "Lagarde", "Alta Vista", "Bodega Chandon", "Pulenta Estate"], "sources": [["Wines of Argentina: DOC Luján de Cuyo", "https://blog.winesofargentina.com/destacadas/doc-lujan-de-cuyo-2"], ["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"]], "checked": "2026-11-14"};
APXF["ar-lujan-de-cuyo-2"] = {"lede": "Alongside the DOC, the department of Luján de Cuyo is also registered as a plain IG with identical limits.", "facts": [["Category", "IG"], ["Recognized", "2002 (INV Res. C.32/2002)"]], "sections": [["The place", "<p>The IG lets producers name the department without meeting the DOC's extra rules, and most Luján wines on export shelves use it this way.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["In the glass", "<p>Malbec, Cabernet, Bonarda and blends, ripened under strong sun and cooled by mountain nights.</p>"], ["For the exam", "<p>Plain IG covering the same department as the Luján de Cuyo DOC, used by wines that do not follow the DOC rules.</p>"]], "producers": [], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-lunlunta"] = {"lede": "Lunlunta is a riverside district of Maipú, on high terraces above the Mendoza river at about 900 m.", "facts": [["Category", "IG"], ["Recognized", "2005 (INV Res. C.04/2005)"]], "sections": [["The place", "<p>Old Malbec here, including Catena's Angélica vineyard planted in the 1920s, grows on stony alluvium and gives deep but fresh wines.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["In the glass", "<p>Malbec, Cabernet, Bonarda and blends, ripened under strong sun and cooled by mountain nights.</p>"], ["For the exam", "<p>IG in Mendoza province; recognised 2005 (INV Res. C.04/2005).</p>"]], "producers": ["Catena Zapata (Angélica)"], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-maipu"] = {"lede": "Maipú, east of Luján de Cuyo along the Mendoza river at 750 to 1,000 m, is the other half of Mendoza's historic Primera Zona.", "facts": [["Category", "IG"], ["Recognized", "2002 (INV Res. C.32/2002)"], ["Vineyard area", "About 10,666 ha"]], "sections": [["The place", "<p>It is where the 19th-century wine industry concentrated after the 1885 railway arrived: Trapiche, López, Giol's La Colina de Oro and the national wine museum are here. Its riverside districts (Lunlunta, Cruz de Piedra, Barrancas, Russell) have old vineyards on stony alluvium and give classic, ripe Malbec, Cabernet and old-vine Bonarda.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["History", "<p>Maipú was the heartland of Mendoza's old wine industry, with historic wineries such as Trapiche and the Zuccardi family, who began in Maipú in 1963.</p>"], ["In the glass", "<p>Classic, warm-climate Malbec, Cabernet and Bonarda.</p>"], ["For the exam", "<p>'First zone' with Luján de Cuyo; historic wineries; Lunlunta, Barrancas, Russell, Cruz de Piedra.</p>"]], "producers": ["Trapiche", "Bodegas López", "Familia Zuccardi", "Rutini (Coquimbito)", "El Enemigo (Chachingo)"], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-mendoza"] = {"lede": "Mendoza is the province that is Argentine wine to most of the world: about 142,800 ha of vines in 2024 (INV), more than 70% of the national vineyard and of the 2026 grape harvest.", "facts": [["Category", "IG"], ["Recognized", "2002 (INV Res. C.32/2002)"], ["Vineyard area", "About 142,785 ha"], ["Main grapes", "Malbec (39,856 ha in 2024), Bonarda, Cabernet Sauvignon, Cereza, Criolla Grande, Syrah, Chardonnay, Torrontés, Pedro Giménez"]], "sections": [["The place", "<p>The vineyards are irrigated oases strung along the Mendoza, Tunuyán, Diamante and Atuel rivers, fed by Andean snowmelt through a canal network that began with Huarpe and Inca irrigation and was expanded by the Spanish from the 1560s. Rain is scarce (around 200 mm), sunshine abundant, and altitude does the cooling: vineyards run from about 500 m in the east to over 1,500 m in the Uco Valley.</p><p>The province has five broad zones. The Primera Zona of Luján de Cuyo and Maipú, just south of the city, is the historic fine-wine heart. The Uco Valley, 80 to 120 km south-west at 900 to 1,600 m, is the modern star. The East (San Martín, Junín, Rivadavia, Santa Rosa, La Paz) is the volume engine. San Rafael and General Alvear in the south form their own oasis, and Lavalle in the north grows mostly for bulk wine and grape juice. As an IG, 'Mendoza' on a label means the grapes come from anywhere in the province, the usual choice for blends and good-value Malbec.</p><p>Alluvial fans of Andean rivers: stony, calcareous gravels near the mountains, deep sandy and silty soils on the eastern plain; continental desert climate with hail ('la piedra') and the hot, dry Zonda wind as the main hazards.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["History", "<p>Spanish settlers from Chile founded Mendoza in 1561 and planted vines soon after, watered by irrigation channels inherited from the Huarpe people. In 1853 the government of Domingo Faustino Sarmiento hired the French agronomist Michel Aimé Pouget to run a Quinta Agronómica in Mendoza, and he brought French varieties including Malbec; 17 April, the day the project was presented in 1853, is celebrated as World Malbec Day. The railway reached Mendoza from Buenos Aires in 1885, and Italian and Spanish immigrants turned the province into a mass producer of everyday wine for a thirsty domestic market. In the 1990s, after the market collapsed and the economy opened, producers such as Nicolás Catena pushed vineyards uphill and built the export category of Argentine Malbec.</p>"], ["In the glass", "<p>Malbec, Cabernet, Bonarda and blends, ripened under strong sun and cooled by mountain nights.</p>"], ["For the exam", "<p>About 70% of Argentina's vineyards; Pouget 1853; World Malbec Day 17 April; railway 1885; Luján de Cuyo, Maipú, Uco, East, San Rafael.</p>"]], "producers": ["Catena Zapata", "Zuccardi", "Trapiche", "Norton", "Achával-Ferrer", "Terrazas de los Andes", "Salentein", "El Enemigo"], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-pampa-el-cepillo"] = {"lede": "Pampa El Cepillo, recognised in 2019, is the plain south of Paraje Altamira in San Carlos, around 1,000 to 1,100 m.", "facts": [["Category", "IG"], ["Recognized", "2019 (RESOL-2019-1-APN-INV#MAGYP)"]], "sections": [["The place", "<p>It is cold, frost-prone and windswept, with stony, calcareous alluvium; Malbec and Cabernet Franc ripen slowly into firm, fresh wines. Its limits were drawn on geological and climatic criteria.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["In the glass", "<p>Malbec, Cabernet, Bonarda and blends, ripened under strong sun and cooled by mountain nights.</p>"], ["For the exam", "<p>IG in Mendoza province; recognised 2019 (RESOL-2019-1-APN-INV#MAGYP).</p>"]], "producers": [], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-paraje-altamira"] = {"lede": "Paraje Altamira is the alluvial fan of the Tunuyán river in San Carlos, at about 1,000 to 1,150 m, and Argentina's most studied terroir.", "facts": [["Category", "IG"], ["Recognized", "2013 (INV Res. C.44/2013), later enlarged"], ["Main grapes", "Malbec, Cabernet Franc, Semillon, Chardonnay"]], "sections": [["The place", "<p>Its recognition in 2013 followed five years of work including some 200 soil pits; the first zone of 4,790 ha (1,400 ha of vineyard) was later enlarged to about 9,290 ha with 2,800 ha of vines. The legal name carries 'Paraje' because 'Altamira' was a registered trademark.</p><p>The soils are a jumble of rounded river stones coated in white calcium carbonate, over sand and silt, which drain fast and push Malbec to small berries and fine, chalky tannin. Zuccardi built its Valle de Uco winery here in 2016 out of the same stones, and its Piedra Infinita Malbec comes from the fan. Catena's Nicasia vineyard and Achával-Ferrer's Finca Altamira are among the other landmarks. Paraje Altamira wines command among the highest average export prices of any Argentine IG.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["History", "<p>Altamira is the alluvial fan of the Tunuyán river in San Carlos, with stony, calcium-carbonate-coated soils. Growers sold its grapes for decades before Zuccardi, Catena, Achával Ferrer and others made it famous; the IG was recognised in 2013 and later enlarged.</p>"], ["In the glass", "<p>Malbec with tension, red fruit, herbs and a chalky, grainy texture.</p>"], ["For the exam", "<p>San Carlos; alluvial fan of the Tunuyán; IG 2013; Zuccardi Piedra Infinita.</p>"]], "producers": ["Zuccardi (Piedra Infinita)", "Catena Zapata (Nicasia)", "Achával-Ferrer (Finca Altamira)"], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-reduccion"] = {"lede": "La Reducción is a district of Rivadavia in Eastern Mendoza, recognised as an IG in 2020.", "facts": [["Category", "IG"], ["Recognized", "2020 (RESOL-2020-34-APN-INV#MAGYP)"]], "sections": [["The place", "<p>Its name recalls a colonial *reducción*, a settlement where indigenous Huarpe people were gathered; it grows traditional reds.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["In the glass", "<p>Malbec, Cabernet, Bonarda and blends, ripened under strong sun and cooled by mountain nights.</p>"], ["For the exam", "<p>IG in Mendoza province; recognised 2020 (RESOL-2020-34-APN-INV#MAGYP).</p>"]], "producers": [], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-rivadavia"] = {"lede": "Rivadavia, in Eastern Mendoza along the Tunuyán river, has about 13,900 ha of vines (INV 2024).", "facts": [["Category", "IG"], ["Recognized", "2002 (INV Res. C.32/2002)"], ["Vineyard area", "About 13,929 ha"]], "sections": [["The place", "<p>Nicola Catena planted his first Malbec here at La Libertad in 1902, and old-vine Bonarda from the East has become a cult value wine.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["In the glass", "<p>Malbec, Cabernet, Bonarda and blends, ripened under strong sun and cooled by mountain nights.</p>"], ["For the exam", "<p>IG in Mendoza province; part of the first big list of department-level IGs registered by the INV in 2002 (Res. C.32/2002).</p>"]], "producers": ["Catena (Viejito de Rivadavia)"], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-russel"] = {"lede": "Russell (registered as 'Russel') is a district of Maipú with deep soils and long-established vineyards for Malbec and Cabernet Sauvignon.", "facts": [["Category", "IG"], ["Recognized", "2005 (INV Res. C.05/2005)"]], "sections": [["The place", ""], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["In the glass", "<p>Malbec, Cabernet, Bonarda and blends, ripened under strong sun and cooled by mountain nights.</p>"], ["For the exam", "<p>IG in Mendoza province; recognised 2005 (INV Res. C.05/2005).</p>"]], "producers": [], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-san-carlos"] = {"lede": "San Carlos is the southern Uco department, about 8,800 ha of vines (INV 2024), two-thirds of them Malbec.", "facts": [["Category", "IG"], ["Recognized", "2002 (INV Res. C.32/2002)"], ["Vineyard area", "About 8,825 ha"]], "sections": [["The place", "<p>It holds Paraje Altamira, Pampa El Cepillo, Cordón del Cepillo and La Consulta, and a long tradition of growers' cooperatives and old Malbec around La Consulta and Eugenio Bustos.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["In the glass", "<p>Malbec, Cabernet, Bonarda and blends, ripened under strong sun and cooled by mountain nights.</p>"], ["For the exam", "<p>IG in Mendoza province; part of the first big list of department-level IGs registered by the INV in 2002 (Res. C.32/2002).</p>"]], "producers": [], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-san-martin"] = {"lede": "San Martín is the largest vineyard department in Argentina, about 25,800 ha in 2024 (INV), the heart of the Eastern Mendoza oasis along the Mendoza and Tunuyán rivers at 650 to 750 m.", "facts": [["Category", "IG"], ["Recognized", "2002 (INV Res. C.32/2002)"], ["Vineyard area", "About 25,847 ha"]], "sections": [["The place", "<p>Hot, flat and fertile, it produces much of Argentina's everyday wine, grape juice and concentrate, with Criolla Grande, Cereza, Bonarda and Pedro Giménez.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["History", "<p>San Martín is the largest vineyard department in Argentina, in the warm Eastern oasis that supplied the domestic market with Criolla and Cereza table wine for a century.</p>"], ["In the glass", "<p>Inexpensive Malbec, Bonarda and whites; bulk and grape concentrate.</p>"], ["For the exam", "<p>Largest vineyard department in Argentina; Eastern Mendoza.</p>"]], "producers": [], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-san-pablo"] = {"lede": "San Pablo, recognised in 2019, is Uco's highest IG, a cold alluvial terrace in Tunuyán at roughly 1,300 to 1,700 m, where frost and snow are real risks.", "facts": [["Category", "IG"], ["Recognized", "2019 (RESOL-2019-10-APN-INV#MAGYP)"]], "sections": [["The place", "<p>Its limits were drawn by geology and climate rather than politics. Wines are taut and aromatic: Chardonnay, Sauvignon Blanc, Pinot Noir and Malbec with very high acidity. Salentein and Zuccardi are among the growers.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["In the glass", "<p>Cool, high-acid Malbec, Pinot Noir and Chardonnay.</p>"], ["For the exam", "<p>Tunuyán; Uco's highest IG, up to about 1,700 m; IG 2019.</p>"]], "producers": ["Salentein", "Zuccardi"], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-san-rafael"] = {"lede": "San Rafael is Mendoza's southern oasis, an irrigated plain at 450 to 800 m on the Diamante and Atuel rivers, about 230 km south of the city, with about 11,500 ha of vines (INV 2024).", "facts": [["Category", "DOC"], ["Recognized", "DOC: INV Res. C.31/2007"], ["Vineyard area", "About 11,478 ha"]], "sections": [["The place", "<p>French, Italian and Spanish immigrants built it into a fruit-and-wine district from the late 19th century; the Bianchi, Suter and Goyenechea houses are long-standing names. It became Argentina's second DOC in 2007, though the denomination is little used.</p><p>San Rafael is cooler than eastern Mendoza thanks to its southern latitude, and its wines are fresh, fruity and fairly priced: Malbec, Cabernet Sauvignon, Bonarda, Chenin Blanc and sparkling wines. The Cañón del Atuel and the 'Valle Grande' reservoir make it a tourism hub as well.</p>"], ["The rules", "<p>A controlled designation of origin. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["History", "<p>San Rafael began as a frontier fort in 1805 on the Diamante river. Irrigation and immigrants, many of them Italian and French, made it Mendoza's southern oasis; Valentín Bianchi founded his winery here in 1928. Its DOC was recognised in 2007. Hail is the great enemy, and many vineyards are covered with anti-hail netting.</p>"], ["In the glass", "<p>Medium-bodied Malbec, Cabernet Sauvignon and Bonarda; Chenin Blanc; sparkling wine.</p>"], ["For the exam", "<p>Southern Mendoza oasis; DOC 2007; Diamante and Atuel rivers; hail nets; Bianchi 1928.</p>"]], "producers": ["Valentín Bianchi", "Bodega Goyenechea", "Suter", "Algodon Wine Estates"], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"]], "checked": "2026-11-14"};
APXF["ar-san-rafael-2"] = {"lede": "The department of San Rafael is also registered as a plain IG with the same limits as the DOC; producers usually label this simpler designation.", "facts": [["Category", "IG"], ["Recognized", "2002 (INV Res. C.32/2002)"]], "sections": [["The place", ""], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["In the glass", "<p>Malbec, Cabernet, Bonarda and blends, ripened under strong sun and cooled by mountain nights.</p>"], ["For the exam", "<p>Plain IG covering the same department as the San Rafael DOC.</p>"]], "producers": [], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-santa-rosa"] = {"lede": "Santa Rosa, at the south-eastern edge of the Eastern oasis along the Tunuyán river, has about 7,900 ha of vines (INV 2024), mostly for everyday wine.", "facts": [["Category", "IG"], ["Recognized", "2002 (INV Res. C.32/2002)"], ["Vineyard area", "About 7,919 ha"]], "sections": [["The place", ""], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["In the glass", "<p>Malbec, Cabernet, Bonarda and blends, ripened under strong sun and cooled by mountain nights.</p>"], ["For the exam", "<p>IG in Mendoza province; part of the first big list of department-level IGs registered by the INV in 2002 (Res. C.32/2002).</p>"]], "producers": [], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-tunuyan"] = {"lede": "Tunuyán is the central Uco department, about 10,200 ha of vines (INV 2024), from the Tunuyán river plain to the Andean foothills.", "facts": [["Category", "IG"], ["Recognized", "2002 (INV Res. C.32/2002)"], ["Vineyard area", "About 10,197 ha"]], "sections": [["The place", "<p>It contains the IGs of Los Chacayes, Vista Flores and San Pablo, and the area of Los Árboles, where Bodegas Salentein built its cross-shaped winery at the end of the 1990s.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["In the glass", "<p>Malbec, Cabernet, Bonarda and blends, ripened under strong sun and cooled by mountain nights.</p>"], ["For the exam", "<p>IG in Mendoza province; part of the first big list of department-level IGs registered by the INV in 2002 (Res. C.32/2002).</p>"]], "producers": ["Salentein", "Clos de los Siete", "Piedra Negra"], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-tupungato"] = {"lede": "Tupungato is the northernmost Uco department, named after the 6,570-m Tupungato volcano that looms over it.", "facts": [["Category", "IG"], ["Recognized", "2002 (INV Res. C.32/2002; synonym Valle de Tupungato 2006)"], ["Vineyard area", "About 10,587 ha"]], "sections": [["The place", "<p>About 10,600 ha of vines (INV 2024) climb from 900 m to over 1,500 m in Gualtallary. Chandon, in Argentina since 1959, was an early investor here for sparkling base wine; Catena's Adrianna vineyard (1992) showed that the high north-west could make world-class Malbec and Chardonnay.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["In the glass", "<p>Malbec, Cabernet, Bonarda and blends, ripened under strong sun and cooled by mountain nights.</p>"], ["For the exam", "<p>IG in Mendoza province; part of the first big list of department-level IGs registered by the INV in 2002 (Res. C.32/2002).</p>"]], "producers": ["Catena Zapata (Adrianna)", "Bodegas Chandon", "Andeluna", "Zuccardi (Gualtallary)", "El Enemigo"], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-valle-de-uco"] = {"lede": "The Uco Valley is where Argentine wine went uphill and found its future.", "facts": [["Category", "IG"], ["Recognized", "2002 (INV Res. C.37/2002)"], ["Vineyard area", "About 29,609 ha"], ["Main grapes", "Malbec (16,584 ha across its three departments in 2024), Cabernet Franc, Cabernet Sauvignon, Chardonnay, Pinot Noir, Sauvignon Blanc, Semillon"]], "sections": [["The place", "<p>It is a long depression at 900 to 1,600 m between the Andes and a low pre-cordillera, 80 to 120 km south-west of Mendoza city, covering the departments of Tupungato, Tunuyán and San Carlos and watered by the Tunuyán river and Andean streams. Historically it grew fruit, potatoes and some Criolla; the turn came in the 1990s, when Nicolás Catena planted the Adrianna vineyard at about 1,450 m in Gualtallary (1992) and a wave of French, Dutch and Argentine investors followed: Clos de los Siete, Salentein, Andeluna, O. Fournier, and later Zuccardi's winery at Paraje Altamira.</p><p>The valley's soils are alluvial fans pushed out from the Andes: stony and often calcareous near the mountains, with sand and silt further east. Each fan and each terrace behaves differently, so Uco has spawned more district IGs than anywhere else in Argentina (Los Chacayes, Paraje Altamira, San Pablo, Pampa El Cepillo, Vista Flores, La Consulta, El Peral, Cordón del Cepillo, with Gualtallary pending), and producers increasingly label single 'parajes'. The climate is cool for Argentina, with frost and hail as real threats.</p><p>Uco Malbec is fresher and more floral than Luján's, with violet, red fruit, firm chalky tannins and high natural acidity; Cabernet Franc, Chardonnay and Pinot Noir excel too. Valle de Uco is by far Argentina's most used IG: 41% of all IG wine sold in 2022 and 45% of IG exports (INV).</p><p>Alluvial fans from the Andes with river stones, sand and calcium carbonate crusts; 900 to 1,600 m; cool continental climate, about 300 mm of summer rain, frequent hail and spring frost.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["History", "<p>Uco was cattle and fruit country until the 1990s, when growers looked for cooler sites at 900 to 1,600 m under the Andes. Nicolás Catena planted the Adrianna vineyard in Gualtallary in 1992, then thought absurdly high and cold. Michel Rolland and partners started Clos de los Siete at Vista Flores in 1998, Salentein, Andeluna and others followed, and Zuccardi built its Piedra Infinita winery at Paraje Altamira. Within twenty years Uco became the source of Argentina's most acclaimed wines, and its districts drove the wave of small IGs recognised after 2012.</p>"], ["In the glass", "<p>Fresh, floral Malbec with firm, chalky tannin; Cabernet Franc; Chardonnay and Sauvignon Blanc from the highest sites.</p>"], ["For the exam", "<p>Tupungato, Tunuyán, San Carlos; 900 to 1,600 m; Adrianna 1992; Clos de los Siete; Paraje Altamira, Gualtallary, Los Chacayes, San Pablo.</p>"]], "producers": ["Catena Zapata", "Zuccardi", "Salentein", "Clos de los Siete", "Andeluna", "O. Fournier", "Bodega Piedra Negra", "Lurton", "SuperUco", "Altos Las Hormigas", "El Enemigo", "Rutini"], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-vista-flores"] = {"lede": "Vista Flores is the Tunuyán district around which Michel Rolland and partners created Clos de los Siete from 1998: a block of about 850 ha divided among several wineries (Monteviejo, Cuvelier, DiamAndes, Rolland), each making its own wine and contributing to the shared Clos de los Siete blend.", "facts": [["Category", "IG"], ["Recognized", "2012 (INV Res. C.11/2012)"]], "sections": [["The place", "<p>At about 1,000 to 1,200 m, sandy-loam and stony soils give plush, polished Malbec.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["History", "<p>The heart of Clos de los Siete, a joint project begun in 1998 by Michel Rolland and partners who split 850 hectares into separate estates such as Monteviejo, Cuvelier Los Andes, DiamAndes and Rolland's own Val de Flores.</p>"], ["In the glass", "<p>Rich Malbec blends.</p>"], ["For the exam", "<p>Tunuyán; Clos de los Siete (Rolland, 1998); IG 2012.</p>"]], "producers": ["Clos de los Siete", "Monteviejo", "DiamAndes", "Cuvelier Los Andes"], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
APXF["ar-vistalba"] = {"lede": "Vistalba, a small district at about 1,000 m beside Las Compuertas on the north bank of the Mendoza river, was recognised as an IG in 2022.", "facts": [["Category", "IG"], ["Recognized", "2022 (RESOL-2022-12-APN-INV#MAGYP)"]], "sections": [["The place", "<p>Old Malbec on stony soils gives refined, perfumed wines; Carlos Pulenta's Vistalba estate and Fabre Montmayou are based here.</p>"], ["The rules", "<p>A geographical indication. Argentina's origin system rests on Ley 25.163 of 1999, applied by the Instituto Nacional de Vitivinicultura (INV) in Mendoza, which created three tiers. An Indicación de Procedencia (IP) is reserved for table and regional wines. An Indicación Geográfica (IG) names a region, locality or production area no larger than a province (or an already recognised interprovincial zone), justified only when the wine's quality is attributable mainly to its origin; the wine must come from quality grapes produced, harvested, made and bottled in the area, and if it is made elsewhere the label must name both the vineyard area and the larger area that contains winemaking. A Denominación de Origen Controlada (DOC) adds a producers' promotion council and an internal regulation, approved by the INV, that fixes varieties, yields, vine training, winemaking, ageing and tasting controls. A vintage on the label requires at least 85% of that harvest. An IG holder may also use any larger IG that contains it.</p>"], ["In the glass", "<p>Malbec, Cabernet, Bonarda and blends, ripened under strong sun and cooled by mountain nights.</p>"], ["For the exam", "<p>IG in Mendoza province; recognised 2022 (RESOL-2022-12-APN-INV#MAGYP).</p>"]], "producers": ["Vistalba (Carlos Pulenta)", "Fabre Montmayou", "Nieto Senetiner"], "sources": [["Ley 25.163: Vinos y bebidas espirituosas de origen vínico (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/ley-25163-60510/texto"], ["Decreto Reglamentario 57/2004 (Argentina.gob.ar)", "https://www.argentina.gob.ar/normativa/nacional/norma-91880/actualizacion"], ["INV: registering a new Indicación Geográfica", "https://www.argentina.gob.ar/servicio/inscripcion-reconocimiento-proteccion-y-registro-de-una-nueva-indicacion-geografica-ig"]], "checked": "2026-11-14"};
